import{_ as c,C as n,o as h,c as m,j as o,a as s,E as e,a2 as i}from"./chunks/framework.CdvW4CUT.js";const v=JSON.parse('{"title":"Maintain the memory","description":"","frontmatter":{"title":"Maintain the memory"},"headers":[],"relativePath":"en/agent/entretenir.md","filePath":"en/agent/entretenir.md"}'),l={name:"en/agent/entretenir.md"};function u(p,t,g,f,_,y){const r=n("AskExample"),a=n("Ask"),d=n("Capture");return h(),m("div",null,[t[0]||(t[0]=o("h1",{id:"maintain-the-memory",tabindex:"-1"},[s("Maintain the memory "),o("a",{class:"header-anchor",href:"#maintain-the-memory","aria-label":'Permalink to "Maintain the memory"'},"​")],-1)),t[1]||(t[1]=o("p",null,"This journey keeps the folder in good shape: spot defects (a broken link, an orphan note, an unreadable frontmatter…), repair them, and tidy up (rename, move, merge, remove) without breaking links. The application can do part of it alone; the agent takes the rest.",-1)),t[2]||(t[2]=o("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[s("What you ask the agent "),o("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),e(r,{tool:"mem_health_scan"}),e(r,{tool:"mem_health_repair"}),e(a,{say:"Apply that repair.",verb:"mem_health_repair",family:"maintenance",args:'{"apply":true,"plan_id":"3f9a1c0e"}'}),e(a,{say:"Which health tasks fall to me? The summaries to compose, first.",verb:"mem_health_tasks",family:"maintenance",args:'{"kind":"compose-summary"}'}),e(r,{tool:"mem_rename"}),e(r,{tool:"mem_move"}),e(a,{say:"Apply that move.",verb:"mem_move",family:"structure",args:'{"path":"20-knowledge/runner.md","to":"20-knowledge/architecture/runner.md","apply":true}'}),e(a,{say:"Undo the last move.",verb:"mem_move_undo",family:"structure"}),e(a,{say:"Remove the note 20-knowledge/note-de-test.md: it duplicates runner.md.",verb:"mem_remove",family:"structure",args:'{"path":"20-knowledge/note-de-test.md","confirm":true,"reason":"Duplicate of runner.md."}'}),e(a,{say:"On second thought, put that note back.",verb:"mem_restore",family:"structure",args:'{"path":"20-knowledge/note-de-test.md"}'}),t[3]||(t[3]=i('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="check-then-repair" tabindex="-1">Check, then repair <a class="header-anchor" href="#check-then-repair" aria-label="Permalink to &quot;Check, then repair&quot;">​</a></h3><ol><li><a href="/en/reference/mcp/maintenance.html#mem-health-scan"><code>mem_health_scan</code></a> audits the vault. <strong>Read-only</strong>, in all circumstances. <code>category</code> restricts the audit to one category (the list is in the <a href="/en/reference/mcp/maintenance.html#mem-health-scan">reference</a>). Each finding says who can repair it: <code>stage</code> is <code>app</code> (the automatic repair step), <code>agent</code> (a task for the agent) or <code>none</code> (with the reason).</li><li><a href="/en/reference/mcp/maintenance.html#mem-health-repair"><code>mem_health_repair</code></a> applies the fixes whose answer is unique and safe. <strong>By default it is a dry run</strong>: the answer carries a <code>plan_id</code>, the number of fixes and the files concerned, and nothing is written. With <code>apply: true</code>, the agent must hand back that <code>plan_id</code>: without it, or if the memory changed since, <strong>nothing is written</strong>. No other parameter is accepted (<code>dry_run</code> is refused), and nothing is ever deleted.</li><li><a href="/en/reference/mcp/maintenance.html#mem-health-tasks"><code>mem_health_tasks</code></a> lists what calls for judgment: a summary to compose, an orphan note to attach, a link with no safe target, a merge conflict, a moved repository. <code>kind</code> filters by kind, <code>limit</code> (30 by default) and <code>cursor</code> paginate. Each task names the tools to use and its end criterion: the finding disappears from the scan. The agent handles each task, then reruns <code>mem_health_scan</code> to check.</li></ol><h3 id="tidy-up" tabindex="-1">Tidy up <a class="header-anchor" href="#tidy-up" aria-label="Permalink to &quot;Tidy up&quot;">​</a></h3><p>These tools <strong>also rewrite the links</strong> that point to what they move (wikilinks, Markdown links, frontmatter), across the whole vault. <code>rewrite_links: false</code> turns that rewriting off for <code>mem_rename</code>, <code>mem_merge</code> and <code>mem_reclass</code>.</p><ul><li><a href="/en/reference/mcp/structure.html#mem-move"><code>mem_move</code></a> renames or moves a file or folder. <strong>Without <code>apply</code>, it returns the plan and writes nothing</strong>: files moved, each link before and after, links left, warnings, <code>empreinte</code> (the plan&#39;s fingerprint). With <code>apply: true</code>, it applies; if <code>empreinte</code> is given and the vault changed since, nothing is written. It refuses an occupied target, an invalid name, a protected folder, a git operation in progress, or a plan that would break a link.</li><li><a href="/en/reference/mcp/structure.html#mem-rename"><code>mem_rename</code></a> renames a project or domain (<code>old_slug</code>, <code>new_slug</code>); <a href="/en/reference/mcp/structure.html#mem-merge"><code>mem_merge</code></a> merges two projects or two domains of the same kind (<code>source_slug</code>, deleted after the merge, into <code>target_slug</code>); <a href="/en/reference/mcp/structure.html#mem-reclass"><code>mem_reclass</code></a> changes a note&#39;s scope (<code>scope</code>) or zone (<code>zone</code>). These three tools write <strong>as soon as they are called</strong>: they have no dry run. To go back, see <code>mem_move_undo</code> below.</li><li><a href="/en/reference/mcp/structure.html#mem-move-undo"><code>mem_move_undo</code></a> undoes the vault&#39;s <strong>last</strong> move operation (<code>mem_move</code>, <code>mem_rename</code>, <code>mem_reclass</code>, <code>mem_merge</code>, or the same gesture made in the application): files and links return to their previous state. It refuses if a touched file has changed since.</li></ul><h3 id="remove" tabindex="-1">Remove <a class="header-anchor" href="#remove" aria-label="Permalink to &quot;Remove&quot;">​</a></h3><p><a href="/en/reference/mcp/structure.html#mem-remove"><code>mem_remove</code></a> <strong>moves</strong> a note to the vault&#39;s trash (<code>.trash/</code>), with an attached note (date, reason, former path); it never deletes. Its guards:</p><ul><li>a note created by this server during the current session can be removed freely; for <strong>any other</strong>, <code>confirm: true</code> <strong>and</strong> a non-empty <code>reason</code> are required;</li><li>a note cited by others is refused, with the list of citing notes; <code>force: true</code> removes it anyway and returns every link that became dangling;</li><li>it refuses <code>index.md</code>, <code>context.md</code>, <code>history.md</code>, <code>.obsidian/</code> and <code>.trash/</code>, and any removal while a git operation is in progress;</li><li>it writes an audit line in <code>99-meta/migrations/removals.md</code>. A note already pushed stays in git history.</li></ul><p><a href="/en/reference/mcp/structure.html#mem-restore"><code>mem_restore</code></a> puts it back, byte for byte, and refuses if a file already occupies its original path: nothing is ever overwritten.</p><p>Other tidying tools exist, for example <a href="/en/reference/mcp/structure.html#mem-attach"><code>mem_attach</code></a> (attach an orphan note to a project or a domain) or <a href="/en/reference/mcp/structure.html#mem-accept-dangling"><code>mem_accept_dangling</code></a> (declare a deliberate dead link); they are in the <a href="/en/reference/mcp/structure.html">MCP reference</a>.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2>',12)),e(d,{name:"accueil",alt:"The Kessho home screen: at the bottom of the window, the status bar shows the memory's health (HEALTH 100%), the git state and the agent count."}),t[4]||(t[4]=i('<ul><li><strong>Health.</strong> The status bar shows the memory&#39;s <strong>HEALTH</strong>, and the home screen carries the <strong>Memory Health Score</strong>. It counts the anomalies and separates what the application repairs alone from what falls to an agent (&quot;N tasks for an agent&quot;, with <strong>Copy the instruction</strong>). <strong>Prepare the repair</strong> follows the same two-step principle as <code>mem_health_repair</code>: a plan, then <strong>Apply</strong>; an outdated plan is refused. See <a href="/en/guide/home.html">Home</a>.</li><li><strong>Tidy up and remove.</strong> In a zone, a note&#39;s menu offers <strong>Rename</strong>, <strong>Move</strong> and <strong>Remove</strong>, with a preview of the links to update and an <strong>Undo</strong> button to go back; <strong>Remove</strong> sends the note to the trash (<code>.trash</code>) and offers <strong>Remove anyway</strong> when other notes cite it. See <a href="/en/guide/zones.html">Zones</a>.</li><li><strong>What the agent has just changed.</strong> The <strong>freshness indicator</strong> lights up after every agent write and names the zone touched; <strong>Reload</strong> refreshes the screen (see <a href="/en/guide/zones.html">Zones</a>).</li></ul>',1))])}const w=c(l,[["render",u]]);export{v as __pageData,w as default};
